#ifndef __SCAMPTRIE_DYNAMIC_H__
#define __SCAMPTRIE_DYNAMIC_H__

#include "scamptrie_base.h"
#include <cstddef>
#include <vector>

// Live FIB with last-write-wins prefix updates and longest-prefix lookups.
// The live structure is a plain binary trie: every distinct normalized prefix
// is kept (even when redundant), updates only touch their own prefix and every
// lookup is an exact 128-bit longest-prefix match.
class ScampTrieDynamic {
public:
    ScampTrieDynamic() {}

    // Clear host bits, then insert or replace that exact normalized prefix.
    uint32_t insert_prefix(ip6_t prefix, uint8_t len, nexthop_t nh);

    // Longest matching live prefix, or LPM_INVALID_NH.
    nexthop_t lookup(ip6_t ip) const;

    const std::vector<PrefixRec>& fib() const { return fib_.entries(); }
    size_t size() const { return fib_.size(); }

private:
    PrefixTrie fib_;
    friend class MemInit;
};

#endif // __SCAMPTRIE_DYNAMIC_H__
