#ifndef __MEM_INIT_H__
#define __MEM_INIT_H__

#include "image.hpp"
#include "scamptrie_base.h"

class ScampTrieDynamic;

// Converts the live FIB into a detached, compact, self-contained memory image.
// The image is completely independent of the live trie and of every other
// saved image.
class MemInit {
public:
    explicit MemInit(ScampTrieDynamic* trie);

    // Emit the compact packed image of the complete live FIB.
    ImageData capture();

private:
    ScampTrieDynamic* trie_;
};

#endif // __MEM_INIT_H__
