#ifndef SCAMP_TRIE_GRAPH_H
#define SCAMP_TRIE_GRAPH_H

// Canonical logical SCAMP-Trie graph built from a FIB.
//
// Ownership and node semantics (see PROTOCOL.md):
//   * lengths   0..16 -> depth-0 root
//   * lengths  17..64 -> depth-16 root keyed by the high 16 address bits
//   * lengths  65..128 -> depth-64 root keyed by the high 64 address bits
// Branches consume six bits; a node reached after t edges has global depth
// origin+6*t.  A subtree with one or two owned prefixes becomes TYPE4/TYPE5,
// larger subtrees split into local prefixes (relative length 0..5) plus child
// subtrees and become TYPE1/2/3 according to their child count.

#include "scamptrie_base.h"
#include <utility>
#include <vector>

struct GNode {
    int origin = 0;    // 0, 16 or 64
    int level = 0;     // t (edges from the forest root)
    int depth = 0;     // origin + 6*level
    int type = 0;      // 1..5
    int max_len = 0;   // owner maximum prefix length (16, 64 or 128)

    ip6_t region{};    // normalized region prefix of length depth

    // TYPE4/5: inline prefixes; TYPE1/2/3: local prefixes in increasing
    // NI bitmap position order.
    std::vector<PrefixRec> pfx;
